import { writeFileSync } from "node:fs";
import { join } from "node:path";
function writeRecordSentinel(twiningDir) {
  try {
    writeFileSync(
      join(twiningDir, ".last-record"),
      String(Math.floor(Date.now() / 1e3)),
      { encoding: "utf-8" }
    );
  } catch {
  }
}

